@Component("leaveRequest-handler")
@ProcessingGroup("leaveRequest-processing-group")
public class LeaveRequestEventHandler {
	
	// core constructor
	LeaveRequestEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateLeaveRequestEvent
     */
    @EventHandler
    public void handle( CreateLeaveRequestEvent event) {
        entityManager.persist(new LeaveRequest(event.getLeaveRequestId(), event.getRequestNumber(), event.getStartDate(), event.getEndDate(), event.getReason(), event.getHours(), event.getEmployee(), event.getLeavePolicy(), event.getApprovals(), event.getStatus()));
    }

    /*
     * @param	event UpdateLeaveRequestEvent
     */
    @EventHandler
    public LeaveRequest handle( UpdateLeaveRequestEvent event) {
    	entityManager.merge(new LeaveRequest(event.getLeaveRequestId(), event.getRequestNumber(), event.getStartDate(), event.getEndDate(), event.getReason(), event.getHours(), event.getEmployee(), event.getLeavePolicy(), event.getApprovals(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteLeaveRequestEvent
     */
    @EventHandler
    public void on( DeleteLeaveRequestEvent event) {
    	LeaveRequest entity = new LeaveRequest();
   
    	// ------------------------------------------
    	// apply the LeaveRequestId
    	// ------------------------------------------
    	entity.setLeaveRequestId( event.getLeaveRequestId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final LeaveRequestRepository leaveRequestEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(LeaveRequestEventHandler.class.getName());

}
